class SystemClipboard {
  cache = "";
  name() {
    return "system";
  }
  get(type) {
    return type === "selection" ? "" : this.cache;
  }
  set(contents, type) {
    if (type === "selection")
      return;
    this.cache = contents;
    navigator.clipboard?.writeText(contents).catch(() => {
      return;
    });
  }
  refresh() {
    navigator.clipboard?.readText().then((text) => {
      this.cache = text;
    }).catch(() => {
      return;
    });
  }
}

