var base64 = Uint8Array;
async function unpack(data) {
  const bytes = base64.fromBase64 ? base64.fromBase64(data) : Uint8Array.from(atob(data), (c) => c.charCodeAt(0));
  const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream("deflate-raw"));
  return new Uint8Array(await new Response(stream).arrayBuffer());
}
async function wasmBytes(source) {
  const value = typeof source === "function" ? await source() : source;
  if (ArrayBuffer.isView(value))
    return new Uint8Array(value.buffer, value.byteOffset, value.byteLength);
  if (value instanceof ArrayBuffer)
    return new Uint8Array(value);
  if (!value.ok)
    throw new Error(`cannot load ${value.url}: ${value.status}`);
  return new Uint8Array(await value.arrayBuffer());
}
async function loadRegex(source) {
  const bytes = source === undefined ? await unpack((await import("./regex-wasm.js")).default) : await wasmBytes(source);
  return RustRegexEngine.load(bytes);
}

// src/view/syntax.ts
async function loadSyntax(win, source) {
  const bytes = source === undefined ? await unpack((await import("./tree-sitter-wasm.js")).default) : await wasmBytes(source);
  return new SyntaxSessions(await createLoader(bytes), (work) => {
    if (typeof win.requestIdleCallback === "function")
      win.requestIdleCallback(work, { timeout: 2000 });
    else
      win.setTimeout(work, 0);
  });
}

